// Stand for 5 standard 1 cm spectrophotometer cuvettes
// Print orientation: base on XY plane (z = 0), pockets open upward (+Z)

// ---------------- Parameters ----------------
block_x       = 104;    // block length along X (mm)
block_y       = 28;     // block width along Y (mm)
block_z       = 32;     // block height (mm)

pocket_size   = 13.2;   // square pocket side length (mm)
pocket_depth  = 27;     // pocket depth from top face (mm)
pocket_count  = 5;      // number of cuvette pockets
pocket_pitch  = 19.2;   // centre-to-centre spacing along X (mm)

floor_thick   = block_z - pocket_depth; // material below pockets (= 5 mm)

eps           = 0.5;    // overshoot for clean boolean cuts (mm)

$fn = 64;

// Offset of the first pocket centre so the row is centred on the block
row_start_x = -(pocket_count - 1) * pocket_pitch / 2;

// ---------------- Model ----------------
difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_z]);

    // Row of square cuvette pockets, open from the top face
    for (i = [0 : pocket_count - 1]) {
        translate([row_start_x + i * pocket_pitch - pocket_size / 2,
                   -pocket_size / 2,
                   floor_thick])
            cube([pocket_size, pocket_size, pocket_depth + eps]);
    }
}
