    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_h]);

    // Row of square pockets opened from the top
    for (i = [0 : n_pockets - 1]) {
        translate([row_start + i * pocket_pitch - pocket_w / 2,
                   -pocket_d / 2,
                   floor_t])
