```openscad
// Horizontal pipette rest
// Units: mm. Print orientation: base plate on bed (z = 0), uprights build up (+Z).

$fn = 96;

// ---------------- Parameters ----------------
plate_len     = 180;   // base plate length (X)
plate_wid     = 35;    // base plate width (Y)
plate_thk     = 4;     // base plate thickness (Z)

upright_thk   = 10;    // upright thickness along X
upright_h     = 40;    // upright height (top at z = 40)

cradle_r      = 8;     // radius of semicircular cradle notch
cradle_z      = upright_h; // notch centre height (on top edge)
cradle_y      = 0;     // notch centre in Y

eps           = 0.5;   // overcut so cutters pass beyond faces

// ---------------- Model ----------------
module base_plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module upright(side) {
    // side = -1 (left end) or +1 (right end); flush with plate end
    x0 = (side < 0) ? -plate_len/2 : plate_len/2 - upright_thk;
    difference() {
        translate([x0, -plate_wid/2, 0])
            cube([upright_thk, plate_wid, upright_h]);
        // Cradle notch, axis along X, running fully through the upright
        translate([x0 - eps, cradle_y, cradle_z])
            rotate([0, 90, 0])
                cylinder(r = cradle_r, h = upright_thk + 2*eps);
    }
}

union() {
    base_plate();
    for (s = [-1, 1]) upright(s);
}
```

