// Horizontal pipette rest
// Units: mm. Print orientation: base plate on bed (z = 0), building +Z.

$fn = 96;

// ---- Base plate ----
base_len   = 140;   // plate length along X
base_wid   = 40;    // plate width along Y
base_thk   = 6;     // plate thickness (z = 0..6)

// ---- Uprights ----
up_thk     = 10;    // upright thickness along X
up_hgt     = 35;    // upright top height (z = 0..35)

// ---- Cradle notch ----
notch_r    = 8;     // semicircular notch radius
notch_y    = 0;     // notch centre Y
notch_z    = up_hgt;// notch centre Z (on top edge)

eps        = 0.5;   // cutter overshoot past faces

module upright(xc) {
    difference() {
        translate([xc - up_thk/2, -base_wid/2, 0])
            cube([up_thk, base_wid, up_hgt]);
        // cradle notch, running through upright along X
        translate([xc - up_thk/2 - eps, notch_y, notch_z])
            rotate([0, 90, 0])
                cylinder(r = notch_r, h = up_thk + 2*eps);
    }
}

union() {
    // base plate
    translate([-base_len/2, -base_wid/2, 0])
        cube([base_len, base_wid, base_thk]);

    // uprights flush with each end
    for (s = [-1, 1])
        upright(s * (base_len/2 - up_thk/2));
}
