```openscad
// Horizontal pipette rest
// Base plate with two end uprights, each with a semicircular cradle notch

$fn = 96;

// --- Base plate ---
base_len   = 140;   // plate length along X
base_wid   = 30;    // plate width along Y
base_thk   = 4;     // plate thickness (z = 0..4)

// --- Uprights ---
up_thk     = 8;     // upright thickness along X
up_hgt     = 40;    // upright top height (z = 0..40)

// --- Cradle notch ---
notch_r    = 9;     // semicircular notch radius
notch_z    = up_hgt; // notch centre height (on top edge)
notch_y    = 0;     // notch centre in Y

eps        = 0.5;   // overcut for clean boolean faces

difference() {
    union() {
        // Base plate
        translate([-base_len/2, -base_wid/2, 0])
            cube([base_len, base_wid, base_thk]);

        // Uprights at each end, flush with plate ends
        for (sx = [-1, 1])
            translate([sx > 0 ? base_len/2 - up_thk : -base_len/2, -base_wid/2, 0])
                cube([up_thk, base_wid, up_hgt]);
    }

    // Cradle notches running along X through each upright
    for (sx = [-1, 1])
        translate([sx > 0 ? base_len/2 - up_thk - eps : -base_len/2 - eps, notch_y, notch_z])
            rotate([0, 90, 0])
                cylinder(r = notch_r, h = up_thk + 2*eps);
}
```

