difference() {
    union() {
        // Base plate, centred on origin in XY
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Uprights flush with each end of the plate
        for (s = [-1, 1])
            translate([s > 0 ? plate_len/2 - upright_thk : -plate_len/2,
                       -plate_wid/2, 0])
                cube([upright_thk, plate_wid, upright_h]);
    }

    // Semicircular cradle notches through each upright along X
    for (s = [-1, 1])
        translate([s * (plate_len/2 - upright_thk/2), 0, upright_h])
            rotate([0, 90, 0])
                cylinder(r = notch_r, h = upright_thk + 2*eps, center = true);
