```openscad
// Flat hex-cap wrench for reagent bottles
// Print orientation: flat on bed, z = 0 to plate_t

$fn = 96;

// ---- Dimensions (mm) ----
plate_t      = 5;    // plate thickness (Z)
head_d       = 55;   // round head diameter
handle_w     = 16;   // handle width (Y)
handle_x0    = 0;    // handle start (X)
handle_x1    = 90;   // handle end (X)
hex_af       = 24;   // hex hole across flats
eps          = 0.5;  // cutter overshoot past faces

// Derived
hex_r = (hex_af / 2) / cos(30);  // hex circumradius (corner distance)

difference() {
    union() {
        // Round head centred on origin
        cylinder(d = head_d, h = plate_t);
        // Straight handle along +X, centred on y = 0
        translate([handle_x0, -handle_w / 2, 0])
            cube([handle_x1 - handle_x0, handle_w, plate_t]);
    }
    // Hexagonal hole: circle with 6 segments has a vertex on +X,
    // so two flats lie parallel to the X axis (at y = +/- hex_af/2)
    translate([0, 0, -eps])
        linear_extrude(height = plate_t + 2 * eps)
            circle(r = hex_r, $fn = 6);
}
```

