pocket_pitch = 10;   // centre-to-centre spacing along X (mm)
pocket_flats = [1.9, 2.4, 2.9, 3.4, 4.4, 5.4]; // across-flats sizes, -X to +X (mm)
n_pockets    = len(pocket_flats);               // number of pockets

// ---- Misc ----
overcut = 0.5;       // extension of cutters past top face (mm)

// Circumradius of a hexagon from its across-flats size
function hex_r(f) = f / sqrt(3);

difference() {
    // Main block
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // Hex pockets (circle with $fn=6 has vertices on X axis,
    // so two flats are parallel to the X axis)
    for (i = [0 : n_pockets - 1]) {
        x = (i - (n_pockets - 1)/2) * pocket_pitch;
        translate([x, 0, block_ht - pocket_depth])
            linear_extrude(height = pocket_depth + overcut)
                circle(r = hex_r(pocket_flats[i]), $fn = 6);
    }
}
