// Flat spacer ring - raises an instrument off the bench
// Units: mm

// ---------- Parameters ----------
ring_thickness   = 4;     // ring thickness (Z)
outer_diameter   = 90;    // outer diameter of annulus
inner_diameter   = 66;    // inner diameter of annulus
hole_diameter    = 4.5;   // through-hole diameter
hole_count       = 8;     // number of through-holes
hole_circle_dia  = 78;    // bolt circle diameter
first_hole_angle = 0;     // first hole on +X axis (deg)
cut_extra        = 0.5;   // overshoot for cutting shapes
$fn              = 128;   // smoothness of curves

// ---------- Model ----------
difference() {
    // Solid disc
    cylinder(d = outer_diameter, h = ring_thickness);

    // Central bore
    translate([0, 0, -cut_extra])
        cylinder(d = inner_diameter, h = ring_thickness + 2 * cut_extra);

    // Through-holes on bolt circle
    for (i = [0 : hole_count - 1]) {
        a = first_hole_angle + i * 360 / hole_count;
        translate([hole_circle_dia / 2 * cos(a),
                   hole_circle_dia / 2 * sin(a),
                   -cut_extra])
            cylinder(d = hole_diameter, h = ring_thickness + 2 * cut_extra, $fn = 64);
    }
}
