// Microplate riser
// Units: mm. Print orientation: legs down on the bed, top plate up.

// ---- Top plate ----
plate_x     = 130;  // plate length in X
plate_y     = 100;  // plate width in Y
plate_t     = 4;    // plate thickness
plate_top_z = 50;   // height of the plate's top face

// ---- Legs ----
leg_size    = 15;   // square leg cross-section (X and Y)

// ---- Central window ----
win_x       = 80;   // window length in X
win_y       = 50;   // window width in Y

// ---- Helpers ----
eps         = 0.5;  // extension of cutting shapes past the faces they cut
overlap     = 0.01; // small overlap so legs fuse with the plate
plate_bot_z = plate_top_z - plate_t;  // underside of the plate (46)

$fn = 64;

module top_plate() {
    difference() {
        translate([-plate_x/2, -plate_y/2, plate_bot_z])
            cube([plate_x, plate_y, plate_t]);
        // Rectangular window through the centre
        translate([-win_x/2, -win_y/2, plate_bot_z - eps])
            cube([win_x, win_y, plate_t + 2*eps]);
    }
}

module legs() {
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx > 0 ? plate_x/2 - leg_size : -plate_x/2,
                   sy > 0 ? plate_y/2 - leg_size : -plate_y/2,
                   0])
            cube([leg_size, leg_size, plate_bot_z + overlap]);
}

union() {
    top_plate();
    legs();
}
