// Wall mounting strip with two countersunk screw holes
// Print orientation: flat on bed, countersinks on top face

$fn = 64;

// ---- Bar dimensions ----
bar_length    = 80;    // X length
bar_width     = 24;    // Y width
bar_thickness = 6;     // Z thickness

// ---- Screw holes ----
hole_count    = 2;     // number of holes
hole_spacing  = 50;    // centre-to-centre distance along X
hole_d        = 4.5;   // through-hole diameter

// ---- Countersink ----
csk_d         = 9;     // countersink diameter at top surface
csk_angle     = 90;    // included angle (degrees)
csk_depth     = (csk_d - hole_d) / 2 / tan(csk_angle / 2); // = 2.25 mm for 90 deg

// ---- Cutting overlap ----
eps           = 0.5;   // extension past faces to avoid coplanar faces

module countersunk_hole() {
    // Through hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = bar_thickness + 2 * eps);
    // Countersink cone, extended above top face keeping the 90-degree angle
    translate([0, 0, bar_thickness - csk_depth])
        cylinder(d1 = hole_d,
                 d2 = csk_d + 2 * eps * tan(csk_angle / 2),
                 h  = csk_depth + eps);
}

difference() {
    // Bar centred in X/Y, resting on z = 0
    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thickness]);

    // Holes along X at y = 0, centred on the bar
    for (i = [0 : hole_count - 1])
        translate([(i - (hole_count - 1) / 2) * hole_spacing, 0, 0])
            countersunk_hole();
}
