notch_d     = 10;   // notch depth into plate (along -Y)
notch_pitch = 16;   // centre-to-centre spacing (X)

eps = 0.5;          // cutter overshoot past faces

difference() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Notches along +Y edge, centred along X
    for (i = [0 : notch_count - 1]) {
        x_c = (i - (notch_count - 1)/2) * notch_pitch;
        translate([x_c - notch_w/2, plate_wid/2 - notch_d, -eps])
            cube([notch_w, notch_d + eps, plate_thk + 2*eps]);
    }
}
